export const petNames={'moss-hornling':'Moss Hornling','antler-bean':'Antler Bean',inkling:'Inkling','pebble-wisp':'Pebble Wisp','moon-puff':'Moon Puff',mothling:'Mothling','bloom-snail':'Bloom Snail','velvet-batling':'Velvet Batling','sprig-dragon':'Sprig Dragon','star-toadlet':'Star Toadlet','snow-owl':'Moonveil Owl','night-spider':'Nocturne Spider'};
export function petLevel(pet,species){return Math.max(1,Math.min(5,Number(pet.petLevels?.[species])||(pet.species===species?Number(pet.highestStage):0)||1));}
export function evolutionGoal(pet,species,target){const level=petLevel(pet,species),to=Math.max(2,Math.min(5,Number(target)||level+1)),cost=[50,90,140,200].slice(level-1,to-1).reduce((a,b)=>a+b,0),balance=Math.max(0,Number(pet.masteryPoints)||0);return{level,target:to,cost,balance,remaining:Math.max(0,cost-balance),unlocked:level>=to,ready:level>=to||balance>=cost};}
export function goalView(goal,state,pet,{outfits,scenes,requirements,stats}){
 if(goal?.kind==='pet'&&petNames[goal.id]){const x=evolutionGoal(pet,goal.id,goal.level);return{...goal,...x,name:`${petNames[goal.id]} · Level ${x.target}`,rows:[{label:'Mastery Points',current:Math.min(x.cost,x.balance),target:x.cost,met:x.ready}],detail:x.unlocked?'Evolution unlocked':x.ready?'Enough MP · ready to evolve':`${x.remaining} MP to go`,href:'/pet/#petGrowth'};}
 const kind=goal?.kind==='scene'?'scene':'outfit',item=(kind==='scene'?scenes:outfits).find(x=>x.id===goal?.id);if(!item)return null;
 const unlocked=!!item.free||(kind==='scene'?state.unlockedScenes:state.unlockedOutfits)?.includes(item.id),rows=requirements(item.needIf,stats(state));return{kind,id:item.id,name:item.name,art:item.art,rows,ready:unlocked,unlocked,detail:unlocked?(kind==='scene'?'Ready to use':'Ready to wear'):item.bossOnly?'Complete its Weekly Boss mission':rows.length?rows.filter(r=>!r.met).map(r=>`${Math.max(0,r.target-r.current)} more ${r.key==='xp'?'XP':r.key==='companionMasteries'?'new Mastery Leaves':r.key==='studyDays'?'study days':r.key==='streak'?'streak days':r.label}`).join(' · ')||'Requirements met · reward is syncing':item.need||'See the reward requirements',href:kind==='scene'?'/garden':'/scholar'};
}
export function firstGoal(pet){const id=petNames[pet.species]?pet.species:'moss-hornling',level=petLevel(pet,id);return level<5?{kind:'pet',id,level:level+1}:null;}
export function celebrationToken(view){return view?.ready?`${view.kind}:${view.id}:${view.target||''}:${view.unlocked?'unlocked':'mp-ready'}`:null;}
